package in.foodcart.api; import in.foodcart.data.*; import in.foodcart.service.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final CheckoutService checkout;private final AuthService auth;private final OrderRepository orders;private final in.foodcart.service.payments.PaymentService payments;public OrderController(CheckoutService c,AuthService a,OrderRepository o,in.foodcart.service.payments.PaymentService p){checkout=c;auth=a;orders=o;payments=p;}/** Creates the order unpaid and starts the payment; the order reaches the vendor once the payment is confirmed. */ @PostMapping public java.util.Map<String,Object> create(@RequestHeader("Authorization") String header,@RequestBody CheckoutService.Request request){OrderEntity o=checkout.create(auth.actor(header,"CUSTOMER"),request);in.foodcart.service.payments.PaymentService.Started payment=payments.start(o);return java.util.Map.of("order",o,"payment",payment);}@GetMapping("/{id}") public OrderEntity get(@RequestHeader("Authorization") String header,@PathVariable String id){String customer=auth.actor(header,"CUSTOMER");OrderEntity o=orders.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found"));if(!o.customerId.equals(customer))throw new SecurityException("Order not found");return o;}}
